// Renders docs/index.html from window.DATA (docs/data.js, generated by `vocab page` from reports/*.json).
(function () {
  const D = window.DATA || {};
  const T = D.text || {};
  const css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  const C = { gemma: css('--s1'), clap: css('--s2'), chance: css('--mut'), fg: css('--fg'), soft: css('--soft'),
              mut: css('--mut'), rule: css('--rule'), hl: css('--hl'), ok: css('--ok'), bad: css('--bad') };
  const FAMC = {}; ['--s1', '--s2', '--s3', '--s4', '--s5', '--s7', '--s6'].forEach((v, i) => { if (D.families) FAMC[D.families[i]] = css(v); });
  const FN = f => (D.family_names || {})[f] || f;
  const $ = id => document.getElementById(id);
  const pct = x => x == null ? '–' : Math.round(x * 100) + '%';
  const f2 = x => x == null ? '–' : (+x).toFixed(2);
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const lab = s => String(s).replace(/_and_/g, ' / ').replace(/_/g, ' ');
  const DS = { esc50: 'ESC-50', fsd50k: 'FSD50K', vocalsound: 'VocalSound', xenocanto: 'xeno-canto', cremad: 'CREMA-D', fma: 'FMA', musopen: 'Musopen', mtg: 'MTG-Jamendo' };
  const base = (extra) => Object.assign({
    paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)', font: { family: 'IBM Plex Sans, sans-serif', color: C.soft, size: 12 },
    margin: { l: 10, r: 10, t: 6, b: 36 }, showlegend: false, hoverlabel: { bgcolor: '#1c2230', bordercolor: C.rule, font: { color: C.fg } },
    xaxis: { gridcolor: C.rule, zerolinecolor: C.rule, tickformat: '.0%', automargin: true },
    yaxis: { gridcolor: 'rgba(0,0,0,0)', automargin: true },
  }, extra || {});
  const cfg = { displayModeBar: false, responsive: true };
  const plot = (id, data, layout) => {
    if (!$(id) || !window.Plotly) return;
    const L = base(layout);
    ['xaxis', 'yaxis'].forEach(a => { L[a] = Object.assign({ automargin: true }, L[a]); });  // per-chart axis overrides keep labels visible
    Plotly.newPlot(id, data, L, cfg);
  };
  const legend = (id, items) => { if ($(id)) $(id).innerHTML = items.map(([n, c, shape]) => `<span><i style="background:${c};${shape === 'ring' ? 'background:none;border:2px solid ' + c : ''}"></i>${esc(n)}</span>`).join(''); };
  const bullets = (id, arr) => { if ($(id)) $(id).innerHTML = (arr || []).map(b => `<li>${b}</li>`).join(''); };
  const text = (id, s) => { if ($(id) && s != null) $(id).innerHTML = s; };
  const tile = (big, l) => `<div class="box tile"><div class="big">${big}</div><div class="l">${l}</div></div>`;

  // ---------- plain-language layer (EXPLAINED.md structure) ----------
  if (T.p_emo_tiles) T.emo_tiles = T.p_emo_tiles;
  if (T.p_music_tiles) T.music_tiles = T.p_music_tiles;
  text('p-tagline', T.p_tagline); bullets('p-headlines', T.p_headlines); text('p-hero-note', T.p_hero_note);
  bullets('p-story', T.p_story); bullets('p-data-lead', T.p_data_lead);
  text('p-takeaway', T.p_takeaway); text('p-hero-chart-note', T.p_hero_chart_note);
  ['p_f1', 'p_f2', 'p_f3', 'p_f4', 'p_f4b', 'p_f5', 'p_business', 'p_glossary'].forEach(k => bullets(k.replace('_', '-'), T[k]));
  if ($('tbl-which') && T.p_which) $('tbl-which').innerHTML = '<tr><th>If you want to…</th><th>Use</th><th>Why</th></tr>' +
    T.p_which.map(r => `<tr><td>${r[0]}</td><td><b>${r[1]}</b></td><td class="mut">${r[2]}</td></tr>`).join('');
  const PZ = T.pz_rows || [];
  if (PZ.length) {  // hero dumbbell: probe (dot) vs typed word (ring), one line per model
    const SHORT = { esc50: 'Everyday sounds', fsd50k: 'Fine sounds', vocalsound: 'Vocal sounds', xenocanto: 'Bird species', cremad: 'Emotion', fma: 'Music genre' };
    const n = PZ.length, yv = PZ.map((r, i) => n - 1 - i), tr = [];
    ['gemma', 'clap'].forEach((m, k) => {
      const nm = m === 'gemma' ? 'Gemma' : 'CLAP', off = k ? -0.17 : 0.17;
      PZ.forEach((r, i) => tr.push({ type: 'scatter', mode: 'lines', x: [r[m].zs, r[m].probe], y: [yv[i] + off, yv[i] + off], line: { color: C[m], width: 3 }, opacity: .55, hoverinfo: 'skip' }));
      tr.push({ type: 'scatter', mode: 'markers', x: PZ.map(r => r[m].probe), y: yv.map(v => v + off), text: PZ.map(r => SHORT[r.id] || r.name),
                marker: { size: 11, color: C[m], line: { color: '#141922', width: 1.5 } }, hovertemplate: '%{text}<br>' + nm + ' probe: %{x:.0%}<extra></extra>' });
      tr.push({ type: 'scatter', mode: 'markers', x: PZ.map(r => r[m].zs), y: yv.map(v => v + off), text: PZ.map(r => SHORT[r.id] || r.name),
                marker: { size: 10, color: '#141922', line: { color: C[m], width: 2.5 } }, hovertemplate: '%{text}<br>' + nm + ' typed word: %{x:.0%}<extra></extra>' });
    });
    tr.push({ type: 'scatter', mode: 'markers', x: PZ.map(r => r.chance), y: yv, marker: { symbol: 'line-ns-open', size: 28, color: C.mut, line: { width: 1.5 } }, hovertemplate: 'guessing: %{x:.0%}<extra></extra>' });
    plot('ch-hero2', tr, { height: 330, xaxis: { range: [0, 1.02], tickformat: '.0%', gridcolor: C.rule },
      yaxis: { tickvals: yv, ticktext: PZ.map(r => SHORT[r.id] || r.name), range: [-0.6, n - 0.4], gridcolor: 'rgba(0,0,0,0)' } });
    legend('lg-hero2', [['Gemma', C.gemma], ['CLAP', C.clap], ['in the model (probe)', C.soft], ['typed word finds it', C.soft, 'ring'], ['guessing', C.mut]]);
  }
  if (PZ.length) {
    const y = PZ.map(r => r.name).reverse(), rows = PZ.slice().reverse(), light = { gemma: 'rgba(57,135,229,.35)', clap: 'rgba(217,89,38,.35)' };
    const tr = [];
    ['gemma', 'clap'].forEach(m => {
      const nm = m === 'gemma' ? 'Gemma' : 'CLAP';
      tr.push({ type: 'bar', orientation: 'h', name: nm + ': probe (in the model)', y, x: rows.map(r => r[m].probe), marker: { color: C[m] }, customdata: rows.map(r => r.id),
                offsetgroup: m + 'p', hovertemplate: '%{y}<br>' + nm + ' probe: %{x:.0%}<extra></extra>' });
      tr.push({ type: 'bar', orientation: 'h', name: nm + ': typed word', y, x: rows.map(r => r[m].zs), marker: { color: light[m], line: { color: C[m], width: 1.5 } }, customdata: rows.map(r => r.id),
                offsetgroup: m + 'z', hovertemplate: '%{y}<br>' + nm + ' typed word: %{x:.0%}<extra></extra>' });
    });
    tr.push({ type: 'scatter', mode: 'markers', y, x: rows.map(r => r.chance), marker: { symbol: 'line-ns-open', size: 26, color: C.fg, line: { width: 2 } }, hovertemplate: 'guessing: %{x:.0%}<extra></extra>' });
    plot('ch-pz', tr, { barmode: 'group', bargap: .25, bargroupgap: .05, xaxis: { range: [0, 1], tickformat: '.0%', gridcolor: C.rule }, height: 420 });
    legend('lg-pz', [['Gemma: in the model (probe)', C.gemma], ['Gemma: typed word', light.gemma], ['CLAP: in the model (probe)', C.clap], ['CLAP: typed word', light.clap], ['guessing', C.fg]]);
    $('ch-pz').on && $('ch-pz').on('plotly_click', ev => {
      const id = ev.points[0].customdata; if (!id) return;
      const box = $('drill-pz'); box.classList.add('on');
      const row = PZ.find(r => r.id === id);
      if (['esc50', 'fsd50k', 'vocalsound', 'xenocanto'].includes(id)) {
        const g = cls.filter(c => c.model === 'gemma' && c.dataset === id), c = cls.filter(c => c.model === 'clap' && c.dataset === id);
        const byGap = g.slice().sort((a, b) => (b.probe - b.zero_shot) - (a.probe - a.zero_shot));
        const cc = l => c.find(x => x.label === l) || {};
        box.innerHTML = `<h3 style="margin-top:0">${esc(row.name)}: every class, biggest "knows but can't name" first (Gemma)</h3><div class="scroll" style="max-height:360px;overflow:auto"><table><tr><th>Sound</th><th class="n">Gemma probe</th><th class="n">Gemma typed word</th><th class="n">CLAP probe</th><th class="n">CLAP typed word</th></tr>` +
          byGap.map(x => `<tr><td>${esc(lab(x.label))}</td><td class="n">${pct(x.probe)}</td><td class="n">${pct(x.zero_shot)}</td><td class="n">${pct(cc(x.label).probe)}</td><td class="n">${pct(cc(x.label).zero_shot)}</td></tr>`).join('') + '</table></div>';
      } else if (id === 'cremad' && D.p6) {
        box.innerHTML = `<h3 style="margin-top:0">Emotion: found by a probe vs by typing the emotion</h3><table><tr><th>Emotion</th><th class="n">Gemma probe</th><th class="n">Gemma typed</th><th class="n">CLAP probe</th><th class="n">CLAP typed</th></tr>` +
          D.p6.labels.map(e => `<tr><td>${e}</td><td class="n">${pct(D.p6.gemma.emotion_recall[e])}</td><td class="n">${pct(D.p6.gemma.zero_shot.raw.recall[e])}</td><td class="n">${pct(D.p6.clap.emotion_recall[e])}</td><td class="n">${pct(D.p6.clap.zero_shot.raw.recall[e])}</td></tr>`).join('') + '</table>';
      } else if (id === 'fma' && D.p7) {
        const g = D.p7.gemma.genre, z = g.zero_shot[g.best_form], c = D.p7.clap.genre, zc = c.zero_shot[c.best_form];
        box.innerHTML = `<h3 style="margin-top:0">Music genre: found by a probe vs by typing the genre</h3><table><tr><th>Genre</th><th class="n">Gemma probe</th><th class="n">Gemma typed</th><th class="n">CLAP probe</th><th class="n">CLAP typed</th></tr>` +
          g.words.map(w => `<tr><td>${w}</td><td class="n">${pct(g.probe_recall[w])}</td><td class="n">${pct(z.recall_report[w])}</td><td class="n">${pct(c.probe_recall[w])}</td><td class="n">${pct(zc.recall_report[w])}</td></tr>`).join('') + '</table>';
      }
    });
  }

  // ---------- hero ----------
  text('tagline', T.tagline);
  bullets('headlines', T.headlines);
  text('scope', T.scope);
  const fam = (D.p4 && D.p4.families) || [];
  function heroRows() {
    // one row per (dataset, family); both models
    const keys = [];
    fam.forEach(r => { const k = r.dataset + '|' + r.family; if (!keys.includes(k)) keys.push(k); });
    keys.sort((a, b) => {
      const [da, fa] = a.split('|'), [db, fb] = b.split('|');
      return D.families.indexOf(fa) - D.families.indexOf(fb) || da.localeCompare(db);
    });
    return keys;
  }
  if (fam.length) {
    const keys = heroRows().reverse();
    const yl = keys.map(k => { const [d, f] = k.split('|'); return `${FN(f)} · ${DS[d]}`; });
    const get = (m, k) => fam.find(r => r.model === m && r.dataset + '|' + r.family === k);
    const tr = ['gemma', 'clap'].map(m => ({
      type: 'scatter', mode: 'markers', name: m === 'gemma' ? 'EmbeddingGemma 2' : 'CLAP', y: yl,
      x: keys.map(k => (get(m, k) || {}).probe ? get(m, k).probe.acc : null),
      error_x: { type: 'data', symmetric: false, array: keys.map(k => { const r = get(m, k); return r ? r.probe.ci[1] - r.probe.acc : 0; }),
                 arrayminus: keys.map(k => { const r = get(m, k); return r ? r.probe.acc - r.probe.ci[0] : 0; }), color: C[m], thickness: 1.5, width: 0 },
      marker: { size: 10, color: C[m], line: { color: '#0d1016', width: 2 } },
      customdata: keys, hovertemplate: '%{y}<br>' + (m === 'gemma' ? 'Gemma' : 'CLAP') + ' probe accuracy %{x:.0%}<extra></extra>' }));
    tr.push({ type: 'scatter', mode: 'markers', name: 'chance', y: yl, x: keys.map(k => (get('gemma', k) || get('clap', k)).chance),
              marker: { symbol: 'line-ns-open', size: 14, color: C.chance }, hovertemplate: 'chance %{x:.0%}<extra></extra>' });
    plot('ch-hero', tr, { xaxis: { range: [0, 1.02], tickformat: '.0%', gridcolor: C.rule, title: { text: 'linear-probe accuracy within the family (grouped CV)', font: { size: 11 } } }, height: Math.max(360, 26 * keys.length + 60) });
    legend('lg-hero', [['EmbeddingGemma 2', C.gemma], ['CLAP', C.clap], ['chance', C.chance]]);
    $('ch-hero').on && $('ch-hero').on('plotly_click', ev => {
      const k = ev.points[0].customdata; if (!k) return;
      const [d, f] = k.split('|'), g = get('gemma', k), c = get('clap', k);
      const cls = Object.keys((g || c).per_class);
      $('drill-hero').classList.add('on');
      $('drill-hero').innerHTML = `<h3 style="margin-top:0">${FN(f)} · ${DS[d]}: per class (recall within the family)</h3>
        <div class="scroll"><table><tr><th>Class</th><th class="n">Gemma probe</th><th class="n">Gemma zero-shot</th><th class="n">CLAP probe</th><th class="n">CLAP zero-shot</th></tr>
        ${cls.map(x => `<tr><td>${esc(lab(x))}</td><td class="n">${pct(g && g.per_class[x].probe)}</td><td class="n">${pct(g && g.per_class[x].zero_shot)}</td><td class="n">${pct(c && c.per_class[x].probe)}</td><td class="n">${pct(c && c.per_class[x].zero_shot)}</td></tr>`).join('')}</table></div>
        ${g && g.pairs_below.length ? `<p class="mut" style="font-size:13px">Pairs Gemma separates below the threshold: ${g.pairs_below.map(p => `${esc(lab(p[0]))} vs ${esc(lab(p[1]))} (${pct(p[2])})`).join('; ')}</p>` : ''}`;
    });
  }

  if ($('ds-cards') && D.datasets) {
    const cnt = (D.counts && D.counts.items) || {};
    $('ds-cards').innerHTML = D.datasets.map(d => `<div class="box dcard"><div class="k">${esc(d.kind || '')}</div><h3>${esc(d.name)}</h3>
      <p>${d.plain || esc(d.what)}</p><p><b>Why we chose it:</b> ${d.why || ''}</p>
      <div class="meta">${cnt[d.id] != null ? cnt[d.id].toLocaleString() + ' items used' : ''} · licence: ${esc(d.licence)}</div></div>`).join('');
  }

  // ---------- data ----------
  text('data-lead', T.data_lead);
  if ($('tbl-data') && D.datasets) {
    const cnt = (D.counts && D.counts.items) || {};
    $('tbl-data').innerHTML = `<tr><th>Dataset</th><th>What</th><th class="n">Items</th><th>Licence</th><th>Playback on a public page</th></tr>` +
      D.datasets.map(d => `<tr><td><b>${d.name}</b></td><td>${esc(d.what)}</td><td class="n">${cnt[d.id] != null ? cnt[d.id].toLocaleString() : '<span class="pill bad">missing</span>'}</td><td>${esc(d.licence)}</td><td>${esc(d.play)}</td></tr>`).join('');
  }

  // ---------- Q1 ----------
  text('hear-lead', T.hear_lead);
  const sib = T.sibling_rows || [];
  if (sib.length) {
    const y = sib.map(r => r.name).reverse(), rows = sib.slice().reverse();
    const tr = ['gemma', 'clap'].map(m => ({ type: 'scatter', mode: 'markers', y, x: rows.map(r => r[m] && r[m].acc),
      error_x: { type: 'data', symmetric: false, array: rows.map(r => r[m] ? r[m].ci[1] - r[m].acc : 0), arrayminus: rows.map(r => r[m] ? r[m].acc - r[m].ci[0] : 0), color: C[m], thickness: 1.5, width: 0 },
      marker: { size: 10, color: C[m], line: { color: '#141922', width: 2 } }, hovertemplate: '%{y}<br>' + m + ' %{x:.0%}<extra></extra>' }));
    tr.push({ type: 'scatter', mode: 'markers', y, x: rows.map(r => r.chance), marker: { symbol: 'line-ns-open', size: 14, color: C.chance }, hovertemplate: 'chance %{x:.0%}<extra></extra>' });
    plot('ch-sib', tr, { xaxis: { range: [0, 1.02], tickformat: '.0%', gridcolor: C.rule, title: { text: 'probe accuracy within the sibling set', font: { size: 11 } } }, height: Math.max(420, 24 * y.length + 60) });
    legend('lg-sib', [['EmbeddingGemma 2', C.gemma], ['CLAP', C.clap], ['chance', C.chance]]);
  }
  text('vocab-note', T.vocab_note);
  if ($('tbl-vocab') && fam.length) {
    const keys = heroRows();
    $('tbl-vocab').innerHTML = `<tr><th>Family · dataset</th><th class="n">Gemma</th><th class="n">CLAP</th></tr>` + keys.map(k => {
      const [d, f] = k.split('|'); const g = fam.find(r => r.model === 'gemma' && r.dataset === d && r.family === f), c = fam.find(r => r.model === 'clap' && r.dataset === d && r.family === f);
      return `<tr><td>${FN(f)} · ${DS[d]}</td><td class="n">${g ? g.vocab + ' of ' + g.vocab_of : '–'}</td><td class="n">${c ? c.vocab + ' of ' + c.vocab_of : '–'}</td></tr>`; }).join('');
  }
  bullets('nb-hear', T.nb_hear);

  // ---------- Q2 ----------
  text('name-lead', T.name_lead);
  const cls = (D.p4 && D.p4.classes) || [];
  ['gemma', 'clap'].forEach(m => {
    const pts = cls.filter(p => p.model === m && p.dataset !== 'cremad');
    if (!pts.length) return;
    const fams = D.families.filter(f => pts.some(p => p.family === f));
    const tr = fams.map(f => { const q = pts.filter(p => p.family === f); return { type: 'scatter', mode: 'markers', name: FN(f), x: q.map(p => p.probe), y: q.map(p => p.zero_shot),
      text: q.map(p => `${lab(p.label)} (${DS[p.dataset]})`), customdata: q.map(p => [p.dataset, p.label]),
      marker: { size: 8, color: FAMC[f], opacity: .85, line: { color: '#141922', width: 1.5 } }, hovertemplate: '%{text}<br>probe %{x:.0%} · zero-shot %{y:.0%}<extra></extra>' }; });
    tr.push({ type: 'scatter', mode: 'lines', x: [0, 1], y: [0, 1], line: { color: C.mut, dash: 'dot', width: 1 }, hoverinfo: 'skip' });
    plot('ch-name-' + m, tr, { xaxis: { range: [-0.03, 1.03], tickformat: '.0%', gridcolor: C.rule, title: { text: 'what the audio contains (probe recall)', font: { size: 11 } } },
      yaxis: { range: [-0.03, 1.03], tickformat: '.0%', gridcolor: C.rule, title: { text: 'what a word finds (zero-shot recall)', font: { size: 11 } } }, margin: { l: 50, r: 10, t: 6, b: 44 } });
  });
  legend('lg-fam', D.families ? D.families.filter(f => cls.some(p => p.family === f && p.dataset !== 'cremad')).map(f => [FN(f), FAMC[f]]) : []);
  bullets('nb-name', T.nb_name);

  // ---------- Q3 ----------
  text('words-lead', T.words_lead);
  const P5 = D.p5;
  if (P5 && P5.gemma) {
    const concepts = Object.keys(P5.gemma.synonyms.raw);
    $('sel-concept').innerHTML = concepts.map(c => `<option>${c}</option>`).join('');
    const drawSyn = c => {
      const g = P5.gemma.synonyms.raw[c], k = P5.clap && P5.clap.synonyms.raw[c];
      const words = Object.keys(g.precision_at_25_by_word);
      const tr = [['gemma', g], ['clap', k]].filter(x => x[1]).map(([m, s]) => ({ type: 'bar', orientation: 'h', name: m, y: words, x: words.map(w => s.precision_at_25_by_word[w]), marker: { color: C[m] }, hovertemplate: '%{y}: %{x:.0%} of top 25<extra>' + m + '</extra>' }));
      plot('ch-syn', tr, { barmode: 'group', bargap: .25, bargroupgap: .08, xaxis: { range: [0, 1], tickformat: '.0%', gridcolor: C.rule }, yaxis: { autorange: 'reversed', automargin: true }, height: Math.max(360, 30 * words.length) });
      $('syn-tiles').innerHTML = tile(f2(g.text_margin), 'text cohesion (within − across), Gemma') + tile(pct(g.retrieval_overlap_jaccard), 'overlap of the synonyms\' top 25 clips (Jaccard), Gemma') + tile(pct(g.base_rate), 'base rate of the right sound');
    };
    $('sel-concept').onchange = e => drawSyn(e.target.value); drawSyn(concepts[0]);
    legend('lg-syn', [['EmbeddingGemma 2', C.gemma], ['CLAP', C.clap]]);
    const A = P5.gemma.alpha, al = Object.keys(A.tune_acc);
    const famsA = D.families.filter(f => A.report[f]);
    plot('ch-alpha', famsA.map(f => ({ type: 'scatter', mode: 'lines+markers', name: FN(f), x: al.map(Number), y: al.map(a => A.report[f][a]), line: { color: FAMC[f], width: 2 }, marker: { size: 8, color: FAMC[f] }, hovertemplate: FN(f) + ' α=%{x}: %{y:.0%}<extra></extra>' })),
      { xaxis: { tickformat: '.2f', gridcolor: C.rule, title: { text: 'centring strength α (0 = raw, 1 = full)', font: { size: 11 } } }, yaxis: { tickformat: '.0%', gridcolor: C.rule, range: [0, 1] }, margin: { l: 44, r: 10, t: 6, b: 44 } });
    legend('lg-alpha', famsA.map(f => [FN(f), FAMC[f]]));
    text('alpha-note', T.alpha_note);
    const S = P5.gemma.structure, SC = P5.clap ? P5.clap.structure : {};
    $('tbl-struct').innerHTML = `<tr><th>Dataset / family</th><th class="n">Gemma ρ</th><th class="n">CLAP ρ</th><th class="n">classes</th></tr>` +
      Object.keys(S).map(ds => [[DS[ds] + ' (all)', S[ds].all, SC[ds] && SC[ds].all]].concat(Object.keys(S[ds].families).map(f => ['  ' + FN(f), S[ds].families[f], SC[ds] && SC[ds].families[f]])))
        .flat().map(([n, g, c]) => `<tr><td>${esc(n)}</td><td class="n">${g ? f2(g.rho) + (g.p_perm < .05 ? ' <span class="pill ok">p&lt;.05</span>' : '') : '–'}</td><td class="n">${c ? f2(c.rho) : '–'}</td><td class="n">${g ? g.n_classes : '–'}</td></tr>`).join('');
    const G = P5.gemma.gap, GC = P5.clap ? P5.clap.gap : {}, gf = D.families.filter(f => G[f]);
    plot('ch-gap', ['gemma', 'clap'].map(m => ({ type: 'bar', name: m, x: gf.map(FN), y: gf.map(f => (m === 'gemma' ? G : GC)[f] ? (m === 'gemma' ? G : GC)[f].margin : null), marker: { color: C[m] }, hovertemplate: '%{x}: own-class text minus other-class text cosine %{y:.3f}<extra>' + m + '</extra>' })),
      { barmode: 'group', xaxis: { tickformat: '', gridcolor: 'rgba(0,0,0,0)' }, yaxis: { gridcolor: C.rule, title: { text: 'matching − non-matching text↔clip cosine', font: { size: 11 } } }, margin: { l: 50, r: 10, t: 6, b: 50 } });
    legend('lg-gap', [['EmbeddingGemma 2', C.gemma], ['CLAP', C.clap]]);
  }
  bullets('nb-words', T.nb_words);

  // ---------- Q4 ----------
  text('emo-title', T.emo_title); text('emo-lead', T.emo_lead);
  const E = D.p6;
  if (E && E.gemma) {
    const reps = [['gemma', 'EmbeddingGemma 2', C.gemma], ['clap', 'CLAP', C.clap], ['prosody', 'prosody features', css('--s3')], ['prosody_mfcc', 'prosody + MFCC', css('--s4')]].filter(r => E[r[0]]);
    const tasks = [['emotion', 'how (emotion)'], ['sentence', 'what (sentence)'], ['speaker', 'who (speaker)']];
    plot('ch-emo', reps.map(([k, n, c]) => ({ type: 'bar', name: n, x: tasks.map(t => t[1]), y: tasks.map(t => E[k][t[0]].skill), marker: { color: c },
      customdata: tasks.map(t => [E[k][t[0]].acc, E[k][t[0]].chance]), hovertemplate: n + '<br>%{x}: accuracy %{customdata[0]:.0%} (chance %{customdata[1]:.0%})<extra></extra>' })),
      { barmode: 'group', xaxis: { tickformat: '', gridcolor: 'rgba(0,0,0,0)' }, yaxis: { tickformat: '.0%', gridcolor: C.rule, range: [0, 1], title: { text: 'skill = (acc − chance)/(1 − chance)', font: { size: 11 } } }, margin: { l: 50, r: 10, t: 6, b: 36 } });
    legend('lg-emo', reps.map(([, n, c]) => [n, c]));
    const L = E.labels, M = E.gemma.emotion_confusion, rs = M.map(r => r.reduce((a, b) => a + b, 0));
    plot('ch-conf', [{ type: 'heatmap', x: L, y: L, z: M.map((r, i) => r.map(v => v / rs[i])), colorscale: [[0, '#141922'], [1, C.gemma]], showscale: false,
      text: M.map((r, i) => r.map(v => Math.round(100 * v / rs[i]) + '%')), texttemplate: '%{text}', hovertemplate: 'true %{y} → predicted %{x}: %{z:.0%}<extra></extra>' }],
      { xaxis: { tickformat: '', side: 'bottom' }, yaxis: { autorange: 'reversed' }, margin: { l: 44, r: 10, t: 6, b: 36 } });
    $('emo-tiles').innerHTML = (T.emo_tiles || []).map(t => tile(t[0], t[1])).join('');
  }
  bullets('nb-emo', T.nb_emo);

  // ---------- Q5 ----------
  text('music-lead', T.music_lead);
  const G7 = D.p7;
  if (G7 && G7.gemma && G7.gemma.genre.zero_shot) {
    const g = G7.gemma.genre, best = g.zero_shot[g.best_form], words = g.words;
    const P = best.precision_at_25;
    plot('ch-genre', [
      { type: 'bar', orientation: 'h', name: 'precision@25', y: words, x: words.map(w => P[w].precision), marker: { color: C.gemma },
        error_x: { type: 'data', symmetric: false, array: words.map(w => P[w].wilson[1] - P[w].precision), arrayminus: words.map(w => P[w].precision - P[w].wilson[0]), color: C.soft, thickness: 1.2, width: 3 },
        hovertemplate: '%{y}: %{x:.0%} of the 25 nearest are this genre<extra></extra>' },
      { type: 'scatter', mode: 'markers', name: 'base rate', y: words, x: words.map(w => P[w].base_rate), marker: { symbol: 'line-ns-open', size: 16, color: C.hl, line: { width: 2.5 } }, hovertemplate: 'base rate %{x:.0%}<extra></extra>' }],
      { xaxis: { range: [0, 1], tickformat: '.0%', gridcolor: C.rule }, yaxis: { autorange: 'reversed' } });
    legend('lg-gen', [['precision of 25 nearest (Wilson 95%)', C.gemma], ['base rate', C.hl]]);
    plot('ch-genre2', [
      { type: 'scatter', mode: 'markers', name: 'probe', y: words, x: words.map(w => g.probe_recall[w]), marker: { size: 11, color: C.gemma }, hovertemplate: '%{y}: probe recall %{x:.0%}<extra></extra>' },
      { type: 'scatter', mode: 'markers', name: 'zero-shot', y: words, x: words.map(w => best.recall_report[w]), marker: { size: 11, color: C.gemma, symbol: 'circle-open', line: { width: 2 } }, hovertemplate: '%{y}: zero-shot recall %{x:.0%}<extra></extra>' }],
      { xaxis: { range: [0, 1.02], tickformat: '.0%', gridcolor: C.rule }, yaxis: { autorange: 'reversed' } });
    legend('lg-gen2', [['probe (what the audio contains)', C.gemma], ['zero-shot (what the word finds)', C.gemma, 'ring']]);
    $('music-tiles').innerHTML = (T.music_tiles || []).map(t => tile(t[0], t[1])).join('');
    const R = G7.gemma.region;
    $('tbl-region').innerHTML = `<tr><th>Region word</th><th class="n">instrumental tracks</th><th class="n">artists</th><th>in test?</th></tr>` +
      Object.keys(R.counts_instrumental).map(w => `<tr><td>${esc(w)}</td><td class="n">${R.counts_instrumental[w]}</td><td class="n">${R.artists_instrumental[w]}</td><td>${R.words.includes(w) ? '<span class="pill ok">yes</span>' : '<span class="pill">too few</span>'}</td></tr>`).join('');
  }
  if ($('tbl-filter') && D.instrumental) {
    const F = D.instrumental.funnel.genre;
    $('tbl-filter').innerHTML = `<tr><th>Genre</th><th class="n">candidates</th><th class="n">tagged instrumental</th><th class="n">Whisper: instrumental</th><th class="n">Whisper: vocal</th></tr>` +
      Object.keys(F).map(k => `<tr><td>${esc(k)}</td><td class="n">${F[k].candidates}</td><td class="n">${F[k].metadata_instrumental_tag}</td><td class="n">${F[k].whisper_instrumental}</td><td class="n">${F[k].whisper_vocal}</td></tr>`).join('');
  }
  bullets('nb-music', T.nb_music);

  // ---------- Phase 8 ----------
  const W8 = D.p8;
  if (W8 && W8.gemma && W8.gemma.genres) {
    const gs = W8.gemma.genres;
    $('sel-genre').innerHTML = gs.map(g => `<option>${g}</option>`).join('');
    const drawWM = g => {
      text('wm-title', `What makes ${esc(g)} sound "${esc(g)}" to the model?`);
      bullets('wm-lead', (T.wm_lead || {})[g]);
      const r = W8.gemma[g], rc = W8.clap && W8.clap[g], names = Object.keys(r.perturbations.delta);
      const nice = n => ((T.pert_names || {})[n] || W8.perturbations[n] || n);
      // each model's change as a share of its own genre gap (members' score minus others'); raw change if no gap
      const scale = rr => { const P = rr.perturbations, gp = P.member_score_mean - P.non_member_score_mean; return gp > 0 ? gp : null; };
      const sg = scale(r), byShare = sg && (!rc || scale(rc));
      const tr = [['gemma', r], ['clap', rc]].filter(x => x[1]).map(([m, rr]) => { const s = byShare ? scale(rr) : 1, D8 = rr.perturbations.delta; return { type: 'scatter', mode: 'markers', name: m,
        y: names.map(nice), x: names.map(n => D8[n].members.mean / s),
        error_x: { type: 'data', symmetric: false, array: names.map(n => (D8[n].members.hi - D8[n].members.mean) / s), arrayminus: names.map(n => (D8[n].members.mean - D8[n].members.lo) / s), color: C[m], thickness: 1.5, width: 0 },
        marker: { size: 10, color: C[m], line: { color: '#141922', width: 2 } }, hovertemplate: '%{y}<br>' + m + (byShare ? ': %{x:.0%} of the gap' : ': %{x:.3f}') + '<extra></extra>' }; });
      plot('ch-pert', tr, { xaxis: { tickformat: byShare ? '.0%' : '.3f', gridcolor: C.rule, zerolinecolor: C.mut, zerolinewidth: 2,
        title: { text: byShare ? `share of the ${g}-vs-rest gap (−100% = erased)` : `change in ${g} score (no gap to scale by)`, font: { size: 11 } } }, yaxis: { autorange: 'reversed' }, height: 420 });
      legend('lg-pert', [['EmbeddingGemma 2', C.gemma], ['CLAP', C.clap]]);
      const fe = r.features.spearman, fk = Object.keys(fe).sort((a, b) => Math.abs(fe[b].across) - Math.abs(fe[a].across));
      plot('ch-feat', [{ type: 'bar', orientation: 'h', y: fk.map(k => (T.feat_names || {})[k] || k), x: fk.map(k => fe[k].across), marker: { color: fk.map(k => fe[k].across >= 0 ? C.gemma : css('--s5')) }, hovertemplate: '%{y}: ρ = %{x:.2f}<extra></extra>' }],
        { xaxis: { range: [-1, 1], tickformat: '.1f', gridcolor: C.rule, zerolinecolor: C.mut }, yaxis: { autorange: 'reversed' } });
      const I = r.instrument_fixed || {};
      const pi = I.piano && I.piano.auc != null ? I.piano : null;
      const instTop = pi ? `<p style="margin:0 0 8px"><b>Piano only:</b> can the ${esc(g)} score tell ${esc(g)} piano from other piano? <span class="em">${pi.auc_ci[0] > .5 ? 'Yes' : 'Not reliably'}</span> (AUC ${f2(pi.auc)}).</p>` : '';
      $('wm-inst').innerHTML = Object.keys(I).length ? instTop + `<table><tr><th>Instrument</th><th class="n">AUC (95% CI)</th><th class="n">${esc(g)} vs other tracks</th></tr>` + Object.keys(I).map(k => `<tr><td>${k}</td><td class="n">${I[k].auc != null ? f2(I[k].auc) + ` (${f2(I[k].auc_ci[0])}–${f2(I[k].auc_ci[1])})` : '<span class="pill">too few</span>'}</td><td class="n">${I[k].members} vs ${I[k].non_members}</td></tr>`).join('') + '</table>' + `<p class="mut" style="font-size:12.5px">${(T.inst_note || {})[g] || ''}</p>` : '<p class="mut">No MTG-Jamendo tag for this genre.</p>';
      const d = r.descriptors;
      $('wm-desc').innerHTML = `<p style="margin:0">Descriptive words closest to the <b>word</b> "${esc(g)}" vs to the <b>sound</b> of ${esc(g)} tracks.</p><p class="mut" style="font-size:12.5px;margin:4px 0 0">Agreement between the two rankings: ρ = ${f2(d.spearman_text_vs_audio)} (1 = same order).</p><div class="grid2" style="gap:8px;margin-top:6px"><div><b style="font-size:12px">Nearest the word</b><ol style="padding-left:18px;margin:4px 0">${d.top10_text_side.map(x => `<li>${esc(x)}</li>`).join('')}</ol></div><div><b style="font-size:12px">Nearest the sound</b><ol style="padding-left:18px;margin:4px 0">${d.top10_audio_side.map(x => `<li>${esc(x)}</li>`).join('')}</ol></div></div>`;
      $('wm-fp').innerHTML = `<p style="margin:0 0 8px">Other-genre tracks the model rates most "${esc(g)}".</p><table><tr><th>Track</th><th>Really</th><th class="n">${esc(g)} score</th></tr>${r.false_positives.slice(0, 8).map(x => `<tr><td>${esc(x.title || x.track)}<br><span class="mut">${esc(x.artist || '')}</span></td><td>${esc(x.genre)}</td><td class="n">${f2(x.score)}</td></tr>`).join('')}</table>`;
      bullets('nb-wm', (T.nb_wm || {})[g]);
    };
    $('sel-genre').onchange = e => drawWM(e.target.value); drawWM(gs[0]);
  }

  // ---------- bridge ----------
  text('vibe-lead', T.vibe_lead);
  if ($('tbl-bridge') && D.bridge) {
    $('tbl-bridge').innerHTML = `<tr><th>Vibe Search query</th><th>Listener: sounded right</th><th class="n">probe</th><th class="n">zero-shot</th><th>Verdict</th><th>Classes used</th></tr>` +
      D.bridge.rows.map(r => `<tr><td>${esc(r.query)}</td><td class="pips">${Array.from({ length: r.listening_of }, (_, i) => `<span class="${i < r.listening_yes ? 'y' : ''}"></span>`).join('')}</td><td class="n">${pct(r.probe_mean)}</td><td class="n">${pct(r.zero_shot_mean)}</td><td><span class="pill ${r.verdict.startsWith('weak') ? 'bad' : r.verdict.startsWith('knows') ? 'hl' : 'ok'}">${esc(r.verdict)}</span></td><td class="mut" style="font-size:12.5px">${r.classes.map(c => esc(lab(c.label)) + ' (' + DS[c.dataset] + ')').join(', ')}</td></tr>`).join('');
  }
  bullets('nb-vibe', T.nb_vibe);

  // ---------- how ----------
  bullets('how-proto', T.protocol); bullets('how-limits', T.limits); bullets('how-repro', T.repro);
  const U = D.umap;
  const view = (xs, ys) => {  // 1st-99th percentile window, so a few far outliers don't squash the map
    const q = (a, p) => { const s = a.slice().sort((m, n) => m - n); return s[Math.floor(p * (s.length - 1))]; };
    const pad = (lo, hi) => [lo - 0.05 * (hi - lo), hi + 0.05 * (hi - lo)];
    return { xaxis: { visible: false, range: pad(q(xs, .01), q(xs, .99)) }, yaxis: { visible: false, range: pad(q(ys, .01), q(ys, .99)) } };
  };
  if (U && U.audio) {
    const fams = D.families.filter(f => U.audio.family.includes(f));
    plot('ch-umap', fams.map(f => { const ix = U.audio.family.map((x, i) => x === f ? i : -1).filter(i => i >= 0);
      return { type: 'scattergl', mode: 'markers', name: FN(f), x: ix.map(i => U.audio.x[i]), y: ix.map(i => U.audio.y[i]), text: ix.map(i => lab(U.audio.label[i]) + ' · ' + DS[U.audio.dataset[i]]),
        marker: { size: 5, color: FAMC[f], opacity: .7 }, hovertemplate: '%{text}<extra></extra>' }; }),
      Object.assign({ showlegend: true, legend: { orientation: 'h', y: -0.05, font: { size: 11 }, itemsizing: 'constant' }, margin: { l: 4, r: 4, t: 4, b: 4 } }, view(U.audio.x, U.audio.y)));
    const J = U.joint, ti = J.is_text.map((t, i) => t ? i : -1).filter(i => i >= 0), ci = J.is_text.map((t, i) => t ? -1 : i).filter(i => i >= 0);
    plot('ch-joint', [
      { type: 'scattergl', mode: 'markers', x: ci.map(i => J.x[i]), y: ci.map(i => J.y[i]), marker: { size: 3, color: ci.map(i => FAMC[J.family[i]] || C.mut), opacity: .5 }, text: ci.map(i => lab(J.label[i])), hovertemplate: '%{text}<extra></extra>' },
      { type: 'scatter', mode: 'markers', x: ti.map(i => J.x[i]), y: ti.map(i => J.y[i]), marker: { size: 8, color: 'rgba(0,0,0,0)', line: { color: C.hl, width: 1.5 } }, text: ti.map(i => J.label[i]), hovertemplate: 'text: %{text}<extra></extra>' }],
      Object.assign({ margin: { l: 4, r: 4, t: 4, b: 4 } }, view(J.x, J.y)));
    text('joint-note', T.joint_note);
  }
  if ($('tbl-sanity') && D.sanity) {
    $('tbl-sanity').innerHTML = `<tr><th>Check</th><th>Gemma</th><th>CLAP</th></tr>` + Object.keys(D.sanity.gemma).map(k => {
      const show = v => v ? `${v.pass ? '<span class="pill ok">pass</span>' : '<span class="pill bad">fail</span>'} <span class="mut">${esc(Object.entries(v).filter(([kk]) => kk !== 'pass').map(([kk, vv]) => kk + ' ' + (Array.isArray(vv) ? vv.map(f2).join('–') : (typeof vv === 'number' && vv <= 1 && vv > 0 ? f2(vv) : vv))).join(', '))}</span>` : '–';
      return `<tr><td>${esc(k.replace(/^\d_/, '').replace(/_/g, ' '))}</td><td>${show(D.sanity.gemma[k])}</td><td>${show(D.sanity.clap && D.sanity.clap[k])}</td></tr>`; }).join('');
  }
  if ($('foot-attr')) $('foot-attr').innerHTML = '<ul style="padding-left:18px">' + (T.attributions || []).map(a => `<li>${a}</li>`).join('') + '</ul>';
})();
